import z3

weeks = 7
golfers = 32
groups = 8
size = 4

s = z3.SolverFor("QF_FD")

g = [[z3.Int(f'g{w}_{p}') for p in range(golfers)] for w in range(weeks)]

for w in range(weeks):
    for p in range(golfers):
        s.add(g[w][p] >= 0, g[w][p] < groups)
    for gr in range(groups):
        s.add(z3.Sum([z3.If(g[w][p] == gr, 1, 0) for p in range(golfers)]) == size)

for p1 in range(golfers):
    for p2 in range(p1 + 1, golfers):
        s.add(z3.Sum([z3.If(g[w][p1] == g[w][p2], 1, 0) for w in range(weeks)]) <= 1)

for p in range(golfers):
    s.add(g[0][p] == p // size)

for w in range(1, weeks):
    s.add(g[w][0] == 0)

print('added, now check')
res = str(s.check())
print(res)
if res == 'sat':
    m = s.model()
    sol = []
    for w in range(weeks):
        for p in range(golfers):
            val = m.evaluate(g[w][p])
            sol.append(int(str(val)))
    print(sol)
else:
    print('No solution or timeout')

